// MICROI_APIENGINE_CACHE_MULTI_ROUTE_V2
/*
 * V8 Event
 * TableKey: sys_apiengine
 * EventType: SubmitAfterServerV8
 * Version: v2.0.0
 * Function:
 * - 保存后刷新接口引擎 Id、Key、主路由和全部“多路由”缓存。
 * - 多路由使用英文分号分隔；变更或删除时清理全部旧别名。
 * - v3/v6共享Redis时统一写JSON文本，禁止写入System.Dynamic.ExpandoObject。
 */

var formModel = V8.Form || {};
var apiEngineKey = formModel.ApiEngineKey;
var apiEngineId = formModel.Id;
var apiAddress = formModel.ApiAddress;
var apiRoutes = formModel.ApiRoutes;

if((!apiEngineKey || !apiEngineId || typeof apiRoutes === 'undefined') && formModel.Id){
  var latestResult = V8.FormEngine.GetFormData('sys_apiengine', {
    Id: formModel.Id,
    _SelectFields: ['Id', 'ApiEngineKey', 'ApiAddress', 'ApiRoutes', 'IsDeleted']
  });
  if(latestResult && latestResult.Code == 1 && latestResult.Data){
    apiEngineKey = apiEngineKey || latestResult.Data.ApiEngineKey;
    apiEngineId = apiEngineId || latestResult.Data.Id;
    apiAddress = apiAddress || latestResult.Data.ApiAddress;
    if(typeof apiRoutes === 'undefined') apiRoutes = latestResult.Data.ApiRoutes;
    formModel.ApiEngineKey = apiEngineKey;
    formModel.ApiAddress = apiAddress;
    formModel.ApiRoutes = apiRoutes || '';
  }
}

function splitRoutes(value){
  if(!value) return [];
  var seen = {};
  return String(value).split(';').map(function(item){ return item.trim(); }).filter(function(item){
    var lower = item.toLowerCase();
    if(!item || seen[lower]) return false;
    seen[lower] = true;
    return true;
  });
}
function cacheKey(alias){
  return `Microi:${V8.OsClient}:FormData:sys_apiengine:${String(alias).trim().toLowerCase()}`;
}
function aliases(model){
  if(!model) return [];
  return [model.Id, model.ApiEngineKey, model.ApiAddress].concat(splitRoutes(model.ApiRoutes)).filter(function(item){ return !!item; });
}
aliases(V8.OldForm).forEach(function(alias){ V8.Cache.Remove(cacheKey(alias)); });
aliases(formModel).forEach(function(alias){ V8.Cache.Remove(cacheKey(alias)); });

if(!formModel.IsDeleted){
  var cacheJson = JSON.stringify(formModel);
  aliases(formModel).forEach(function(alias){ V8.Cache.Set(cacheKey(alias), cacheJson); });
}

/*
 * V8 Event
 * TableKey: sys_menu
 * EventType: SubmitAfterServerV8
 * Version: v1.0.5
 * Function:
 * - 菜单保存后按当前租户真实管理员角色同步权限，删除时清理菜单授权；不含租户专属角色或菜单固定标识。
 */

// 将按钮配置解析为数组，空值或无效 JSON 返回空数组。
function parseArray(value) {
  if (!value) return [];
  if (Array.isArray(value)) return value;
  try {
    var parsed = JSON.parse(String(value));
    return Array.isArray(parsed) ? parsed : [];
  } catch (ex) {
    return [];
  }
}

// 追加非空按钮标识，避免同一权限重复出现。
function addUnique(target, value) {
  var current = value === null || value === undefined ? '' : String(value);
  if (current && target.indexOf(current) < 0) target.push(current);
}

// 从完整菜单及其按钮构造管理员权限 JSON。
function buildPermission(menu) {
  var result = ['Add', 'Edit', 'Del', 'Export', 'Import'];
  var buttonFields = ['MoreBtns', 'ExportMoreBtns', 'BatchSelectMoreBtns', 'PageBtns', 'PageTabs', 'FormBtns'];
  for (var fieldIndex = 0; fieldIndex < buttonFields.length; fieldIndex++) {
    var buttons = parseArray(menu[buttonFields[fieldIndex]]);
    for (var buttonIndex = 0; buttonIndex < buttons.length; buttonIndex++) {
      var button = buttons[buttonIndex] || {};
      addUnique(result, button.Id);
      addUnique(result, button.Name);
    }
  }
  return JSON.stringify(result);
}

// 在菜单事务内按角色和菜单幂等写入权限，失败结果交给调用方回滚。
function upsertRoleLimit(roleId, menuId, permission) {
  var limitResult = V8.FormEngine.GetFormData('sys_rolelimit', {
    _Where: [['RoleId', '=', roleId], ['FkId', '=', menuId], ['Type', '=', 'Menu']],
    _SelectFields: ['Id']
  }, V8.DbTrans);

  if (limitResult && limitResult.Code === 1 && limitResult.Data) {
    return V8.FormEngine.UptFormData('sys_rolelimit', {
      Id: limitResult.Data.Id,
      Permission: permission
    }, V8.DbTrans);
  }

  if (!limitResult || limitResult.Code !== 2) return limitResult || { Code: 0, Msg: '菜单权限查询失败' };
  return V8.FormEngine.AddFormData('sys_rolelimit', {
    RoleId: roleId,
    FkId: menuId,
    Type: 'Menu',
    CreateTime: DateNow('yyyy-MM-dd HH:mm:ss'),
    Permission: permission
  }, V8.DbTrans);
}

// 删除时同步清理该菜单权限，防止遗留可复用的授权记录。
var action = String(V8.FormSubmitAction || '').toLowerCase();
if (action === 'delete' || action === 'del') {
  var removed = V8.FormEngine.DelFormDataByWhere('sys_rolelimit', {
    _Where: [['FkId', '=', V8.Form.Id], ['Type', '=', 'Menu']]
  }, V8.DbTrans);
  if (!removed || removed.Code !== 1) return removed || { Code: 0, Msg: '菜单权限清理失败' };
} else {
  // 更新可能只携带少量字段，必须在同一事务读取完整菜单以保留按钮权限。
  var menuResult = V8.FormEngine.GetFormData('sys_menu', { Id: V8.Form.Id }, V8.DbTrans);
  if (!menuResult || menuResult.Code !== 1) return menuResult || { Code: 0, Msg: '菜单回读失败' };
  var menuPermission = buildPermission(menuResult.Data);
  var pageIndex = 1;
  while (true) {
    var roles = V8.FormEngine.GetTableData('sys_role', {
      _Where: [['Level', '>=', 9999]], _SelectFields: ['Id'], _PageIndex: pageIndex++, _PageSize: 200
    }, V8.DbTrans);
    if (!roles || roles.Code !== 1) return roles || { Code: 0, Msg: '管理员角色查询失败' };
    for (var roleIndex = 0; roleIndex < roles.Data.length; roleIndex++) {
      var granted = upsertRoleLimit(roles.Data[roleIndex].Id, V8.Form.Id, menuPermission);
      if (!granted || granted.Code !== 1) return granted || { Code: 0, Msg: '管理员菜单授权失败' };
    }
    if (roles.Data.length < 200) break;
  }
}
// 平台方法在事务提交后刷新当前登录投影；回滚时不会提前暴露权限。
if (V8.CurrentUser && V8.CurrentUser.Id) {
  var refreshed = V8.Method.RefreshLoginUser(V8.CurrentUser.Id, V8.OsClient);
  if (!refreshed || refreshed.Code !== 1) return refreshed || { Code: 0, Msg: '登录权限刷新失败' };
}

V8.Cache.Remove(`Microi:${V8.OsClient}:FormData:sys_menu:${V8.Form.Id.toLowerCase()}`);
if (V8.Form.ModuleEngineKey) {
  V8.Cache.Remove(`Microi:${V8.OsClient}:FormData:sys_menu:${V8.Form.ModuleEngineKey.toLowerCase()}`);
}

