    var children = childrenByParent[String(parentModel.Id || '').toLowerCase()] || [];
    for (var childIndex = 0; childIndex < children.length; childIndex++) {
        var child = children[childIndex];
        var childCode = String(parentModel.Code || '') + (childIndex + 1) + '-';
